package com.hms.payments;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="appointment_payment_settings") public class AppointmentPaymentSettings {
 @Id private UUID tenantId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=40) private PaymentMode mode; @Column(nullable=false,length=3) private String currency; @Column(length=2000) private String instructions; @Column(length=180) private String bankAccountName; @Column(length=80) private String bankAccountNumber; @Column(length=20) private String bankIfsc; @Column(length=120) private String upiId; @Column(length=500) private String paymentLink; @Column(nullable=false) private OffsetDateTime updatedAt;
 protected AppointmentPaymentSettings() {} public AppointmentPaymentSettings(UUID tenantId,UpdatePaymentSettingsRequest r){this.tenantId=tenantId;apply(r);} public void apply(UpdatePaymentSettingsRequest r){mode=r.mode();currency=r.currency().toUpperCase();instructions=r.instructions();bankAccountName=r.bankAccountName();bankAccountNumber=r.bankAccountNumber();bankIfsc=r.bankIfsc();upiId=r.upiId();paymentLink=r.paymentLink();updatedAt=OffsetDateTime.now();}
 public UUID getTenantId(){return tenantId;} public PaymentMode getMode(){return mode;} public String getCurrency(){return currency;} public String getInstructions(){return instructions;} public String getBankAccountName(){return bankAccountName;} public String getBankAccountNumber(){return bankAccountNumber;} public String getBankIfsc(){return bankIfsc;} public String getUpiId(){return upiId;} public String getPaymentLink(){return paymentLink;} public OffsetDateTime getUpdatedAt(){return updatedAt;}
}
